import{_ as i,a0 as d,w as r,s as l,ao as o,I as p,x as s,a1 as n,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何用 rpm-ostree 資料庫檢查更新信息和更新日誌 | LCTT x X-CMD","titleTemplate":false,"description":"如何用 rpm-ostree 資料庫檢查更新信息和更新日誌 | LCTT (202109) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何用 rpm-ostree 資料庫檢查更新信息和更新日誌 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何用 rpm-ostree 資料庫檢查更新信息和更新日誌 | LCTT (202109) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202109/20210915 How to check for update info and changelogs with rpm-ostree db","title":"如何用 rpm-ostree 資料庫檢查更新信息和更新日誌","tag":"202109","desc":""},"relativePath":"202109/20210915 How to check for update info and changelogs with rpm-ostree db.md","filePath":"[post].md"}'),f={name:"202109/20210915 How to check for update info and changelogs with rpm-ostree db.md"};function b(c,e,g,m,u,h){const a=d("Link");return r(),l("div",null,[e[20]||(e[20]=o('<h1 id="如何用-rpm-ostree-資料庫檢查更新信息和更新日誌" tabindex="-1">如何用 rpm-ostree 資料庫檢查更新信息和更新日誌 <a class="header-anchor" href="#如何用-rpm-ostree-資料庫檢查更新信息和更新日誌" aria-label="Permalink to “如何用 rpm-ostree 資料庫檢查更新信息和更新日誌”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/09/rpm-ostree-db_changelog-816x345.jpg" alt=""></p><p>這篇文章將教你如何使用 <code>rpm-ostree</code> 資料庫及其子命令檢查更新、檢查更改的軟件包和閲讀更新日誌。</p><p>這些命令將在 Fedora Silverblue 上進行演示，並且應該在任何使用 <code>rpm-ostree</code> 的操作系統上工作。</p><h3 id="簡介" tabindex="-1">簡介 <a class="header-anchor" href="#簡介" aria-label="Permalink to “簡介”">​</a></h3><p>假設你對不可更改的系統感興趣。在基於容器技術構建用例時使用只讀的基本系統聽起來非常有吸引力，它會説服你選擇使用 <code>rpm-ostree</code> 的發行版。</p>',6)),p("p",null,[e[2]||(e[2]=s("你現在發現自己在 ",-1)),n(a,{href:"https://fedoramagazine.org/what-is-silverblue/"},{default:t(()=>[...e[0]||(e[0]=[s("Fedora Silverblue",-1)])]),_:1}),e[3]||(e[3]=s("（或其他類似的發行版）上，你想檢查更新。但你遇到了一個問題。雖然你可以通過 GNOME Software 找到 Fedora Silverblue 上的更新包，但你實際上無法閲讀它們的更新日誌。你也不能 ",-1)),n(a,{href:"https://fedoramagazine.org/use-dnf-updateinfo-to-read-update-changelogs/"},{default:t(()=>[...e[1]||(e[1]=[s("使用 dnf updateinfo 在命令列上讀取它們",-1)])]),_:1}),e[4]||(e[4]=s("，因為主機系統上沒有 DNF。",-1))]),e[21]||(e[21]=o(`<p>那麼，你應該怎麼做呢？嗯，<code>rpm-ostree</code> 有一些子命令可以在這種情況下提供幫助。</p><h3 id="檢查更新" tabindex="-1">檢查更新 <a class="header-anchor" href="#檢查更新" aria-label="Permalink to “檢查更新”">​</a></h3><p>第一步是檢查更新。只需運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpm-ostree upgrade --check</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>AvailableUpdate:</span></span>
<span class="line"><span>        Version: 34.20210905.0 (2021-09-05T20:59:47Z)</span></span>
<span class="line"><span>         Commit: d8bab818f5abcfb58d2c038614965bf26426d55667e52018fcd295b9bfbc88b4</span></span>
<span class="line"><span>   GPGSignature: Valid signature by 8C5BA6990BDB26E19F2A1A801161AE6945719A39</span></span>
<span class="line"><span>  SecAdvisories: 1 moderate</span></span>
<span class="line"><span>           Diff: 4 upgraded</span></span></code></pre></div><p>請注意，雖然它沒有在輸出中告訴更新的軟件包，但它顯示了更新的提交為 <code>d8bab818f5abcfb58d2c038614965bf26426d55667e52018fcd295b9bfbc88b4</code>。這在後面會很有用。</p><p>接下來你需要做的是找到你正在運行的當前部署的提交。運行 <code>rpm-ostree status</code> 以獲得當前部署的<ruby>基提交<rt>BaseCommit</rt></ruby>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpm-ostree status</span></span>
<span class="line"><span>State: idle</span></span>
<span class="line"><span>Deployments:</span></span>
<span class="line"><span>● fedora:fedora/34/x86_64/silverblue</span></span>
<span class="line"><span>                   Version: 34.20210904.0 (2021-09-04T19:16:37Z)</span></span>
<span class="line"><span>                BaseCommit: e279286dcd8b5e231cff15c4130a4b1f5a03b6735327b213ee474332b311dd1e</span></span>
<span class="line"><span>              GPGSignature: Valid signature by 8C5BA6990BDB26E19F2A1A801161AE6945719A39</span></span>
<span class="line"><span>       RemovedBasePackages: ...</span></span>
<span class="line"><span>           LayeredPackages: ...</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>對於這個例子，基提交是<code>e279286dcd8b5e231cff15c4130a4b1f5a03b6735327b213ee474332b311dd1e</code>。</p><p>現在你可以用 <code>rpm-ostree db diff [commit1] [commit2]</code> 找到這兩個提交的差異。在這個命令中，<code>[commit1]</code> 將是當前部署的基提交，<code>[commit2]</code> 將是升級檢查命令中的提交。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpm-ostree db diff e279286dcd8b5e231cff15c4130a4b1f5a03b6735327b213ee474332b311dd1e d8bab818f5abcfb58d2c038614965bf26426d55667e52018fcd295b9bfbc88b4</span></span>
<span class="line"><span>ostree diff commit from: e279286dcd8b5e231cff15c4130a4b1f5a03b6735327b213ee474332b311dd1e</span></span>
<span class="line"><span>ostree diff commit to:   d8bab818f5abcfb58d2c038614965bf26426d55667e52018fcd295b9bfbc88b4</span></span>
<span class="line"><span>Upgraded:</span></span>
<span class="line"><span>  soundtouch 2.1.1-6.fc34 -&gt; 2.1.2-1.fc34</span></span></code></pre></div><p><code>diff</code> 輸出顯示 <code>soundtouch</code> 被更新了，並指出了版本號。通過在前面的命令中加入 <code>-changelogs</code> 來查看更新日誌：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rpm-ostree db diff e279286dcd8b5e231cff15c4130a4b1f5a03b6735327b213ee474332b311dd1e d8bab818f5abcfb58d2c038614965bf26426d55667e52018fcd295b9bfbc88b4 --changelogs</span></span>
<span class="line"><span>ostree diff commit from: e279286dcd8b5e231cff15c4130a4b1f5a03b6735327b213ee474332b311dd1e</span></span>
<span class="line"><span>ostree diff commit to:   d8bab818f5abcfb58d2c038614965bf26426d55667e52018fcd295b9bfbc88b4</span></span>
<span class="line"><span>Upgraded:</span></span>
<span class="line"><span>  soundtouch 2.1.1-6.fc34.x86_64 -&gt; 2.1.2-1.fc34.x86_64</span></span>
<span class="line"><span>    * dom ago 29 2021 Uwe Klotz &lt;uwe.klotz@gmail.com&gt; - 2.1.2-1</span></span>
<span class="line"><span>    - Update to new upstream version 2.1.2</span></span>
<span class="line"><span>      Bump version to 2.1.2 to correct incorrect version info in configure.ac</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    * sex jul 23 2021 Fedora Release Engineering &lt;releng@fedoraproject.org&gt; - 2.1.1-7</span></span>
<span class="line"><span>    - Rebuilt for https://fedoraproject.org/wiki/Fedora_35_Mass_Rebuild</span></span></code></pre></div><p>這個輸出顯示了提交説明以及版本號。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>使用 <code>rpm-ostree db</code>，你現在可以擁有相當於 <code>dnf check-update</code> 和 <code>dnf updateinfo</code> 的功能。</p><p>如果你想檢查你所安裝的更新的詳細信息，這將非常有用。</p><hr>`,17)),p("p",null,[e[6]||(e[6]=s("via: ",-1)),n(a,{href:"https://fedoramagazine.org/how-to-check-for-update-info-and-changelogs-with-rpm-ostree-db/"},{default:t(()=>[...e[5]||(e[5]=[s("https://fedoramagazine.org/how-to-check-for-update-info-and-changelogs-with-rpm-ostree-db/",-1)])]),_:1})]),p("p",null,[e[11]||(e[11]=s("作者：",-1)),n(a,{href:"https://fedoramagazine.org/author/mateusrodcosta/"},{default:t(()=>[...e[7]||(e[7]=[s("Mateus Rodrigues Costa",-1)])]),_:1}),e[12]||(e[12]=s(" 選題：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...e[8]||(e[8]=[s("lujun9972",-1)])]),_:1}),e[13]||(e[13]=s(" 譯者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:t(()=>[...e[9]||(e[9]=[s("geekpi",-1)])]),_:1}),e[14]||(e[14]=s(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:t(()=>[...e[10]||(e[10]=[s("wxy",-1)])]),_:1})]),p("p",null,[e[17]||(e[17]=s("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...e[15]||(e[15]=[s("LCTT",-1)])]),_:1}),e[18]||(e[18]=s(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:t(()=>[...e[16]||(e[16]=[s("Linux中國",-1)])]),_:1}),e[19]||(e[19]=s(" 榮譽推出",-1))])])}const x=i(f,[["render",b]]);export{T as __pageData,x as default};
